A={(0,1),(0,2),(1,0),(1,1),(2,1),(2,2)}
B={(0,0),(0,2),(1,0),(1,1),(1,2),(2,1)}
def variants(P):
 out=[]
 for rot in range(4):
  for refl in (False,True):
   Q=set()
   for r,c in P:
    if refl:c=2-c
    for _ in range(rot):r,c=c,2-r
    Q.add((r,c))
   out.append((rot,refl,Q))
 return out
[(r,f,Q==B) for r,f,Q in variants(A)]
